    public MediaAsset testCreate() throws Throwable {
    MediaAsset entity = null;

    LOGGER.info( "MediaAssetTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a MediaAsset");

    StringBuilder msg = new StringBuilder( "-- Failed to create a MediaAsset" );

    try {
        entity = service.createMediaAsset( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getMediaAssetId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a MediaAsset with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

