    /**
     * Tests getting all MediaAssets.
     *
     * @return    Collection
     */
    public List<MediaAsset> testGetAll() throws Throwable {
    LOGGER.info( "MediaAssetTest:testGetAll() - Retrieving Collection of MediaAssets:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all MediaAsset : " );
    List<MediaAsset> collection  = null;

    try {
        // call the static get method on the MediaAssetService
        collection = service.getAllMediaAsset();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            MediaAsset currEntity  = null;
            Iterator<MediaAsset> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getMediaAssetId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

